#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
using namespace std;

const int MAX_VERTICES = 5500;
const int MAX_ARCS = 35500;
const int INFINITY_COST = 1000000000;

struct NetworkArc {
    int next_arc;
    int destination;
    int capacity;
    int cost;
};

NetworkArc arc[2 * MAX_ARCS + 10];
int adjacency_head[MAX_VERTICES + 1];
int arc_index = 1;

void connect(int u, int v, int cap, int c) {
    arc[++arc_index] = {adjacency_head[u], v, cap, c};
    adjacency_head[u] = arc_index;
    arc[++arc_index] = {adjacency_head[v], u, 0, -c};
    adjacency_head[v] = arc_index;
}

int source_node, sink_node;
int parent_vertex[MAX_VERTICES + 1];
int parent_arc[MAX_VERTICES + 1];
int node_flow[MAX_VERTICES + 1];
int distance[MAX_VERTICES + 1];
bool is_queued[MAX_VERTICES + 1];

int spfa() {
    memset(distance, 0x3f, sizeof(int) * (sink_node + 1));
    memset(node_flow, 0, sizeof(int) * (sink_node + 1));
    node_flow[source_node] = INFINITY_COST;
    distance[source_node] = 0;
    queue<int> Q;
    Q.push(source_node);
    is_queued[source_node] = true;

    while (!Q.empty()) {
        int u = Q.front(); Q.pop();
        is_queued[u] = false;

        for (int e = adjacency_head[u]; e; e = arc[e].next_arc) {
            int v = arc[e].destination;
            if (arc[e].capacity && distance[v] > distance[u] + arc[e].cost) {
                distance[v] = distance[u] + arc[e].cost;
                node_flow[v] = min(node_flow[u], arc[e].capacity);
                parent_arc[v] = e;
                parent_vertex[v] = u;
                if (!is_queued[v]) {
                    is_queued[v] = true;
                    Q.push(v);
                }
            }
        }
    }
    return node_flow[sink_node];
}

int N, M, K, C_val, D_val;
int schedule[105][105];
int edge_state[105][105];
struct Trip { int origin, destination; } trips[105];

#define COORD_NODE(row,col) ((row) * N + (col))

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> N >> M >> K >> C_val >> D_val;

    source_node = COORD_NODE(N+K, N) + 1;
    sink_node = source_node + 2;

    connect(COORD_NODE(0, 1), sink_node, INFINITY_COST, 0);

    for (int i = 1, p; i <= K; ++i) {
        cin >> p;
        connect(source_node, COORD_NODE(0, p), 1, 0);
    }

    for (int i = 1; i <= M; ++i) {
        cin >> trips[i*2].origin >> trips[i*2].destination;
        trips[i*2-1] = {trips[i*2].destination, trips[i*2].origin};
    }
    M <<= 1;

    for (int t = 1; t <= N + K; ++t) {
        for (int i = 1; i <= N; ++i)
            connect(COORD_NODE(t-1, i), COORD_NODE(t, i), INFINITY_COST, 0);
        for (int i = 1; i <= M; ++i) {
            connect(COORD_NODE(t-1, trips[i].origin), COORD_NODE(t, trips[i].destination), 1, D_val);
            schedule[t][i] = arc_index;
            edge_state[t][i] = 1;
        }
        connect(COORD_NODE(t, 1), sink_node, INFINITY_COST, t * C_val);
    }

    int augment_amount, result_cost = 0;
    while (augment_amount = spfa()) {
        int v = sink_node;
        while (v != source_node) {
            int u = parent_vertex[v];
            arc[parent_arc[v]].capacity -= augment_amount;
            arc[parent_arc[v]^1].capacity += augment_amount;
            v = u;
        }
        result_cost += distance[sink_node] * augment_amount;

        for (int t = 1; t <= N + N; ++t)
            for (int i = 1; i <= M; ++i)
                if (arc[schedule[t][i]].capacity) {
                    edge_state[t][i]++;
                    connect(COORD_NODE(t-1, trips[i].origin), COORD_NODE(t, trips[i].destination), 1,
                            D_val * (edge_state[t][i]*2 - 1));
                    schedule[t][i] = arc_index;
                }
    }

    cout << result_cost << '\n';
    return 0;
}
